export type AcademyResource={label:string;url:string;kind:"video"|"guidance"|"interactive"};
export type AcademyCourse={id:string;title:string;category:string;level:"Core"|"Specialist"|"Practical";duration:string;refreshMonths:number|null;refreshNote:string;summary:string;outcomes:string[];lessons:{title:string;teaching:string;activity:string}[];scenario:{prompt:string;choices:string[];best:number;feedback:string};resources:AcademyResource[]};
export const academyCourses:AcademyCourse[]=[
{id:"professional-standards",title:"Professional Standards and Company Procedures",category:"Professional practice",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review, manager-configurable",summary:"Set expectations for readiness, conduct, communication, privacy, handovers and following Swans procedures.",outcomes:["Prepare properly for duty and confirm job instructions","Communicate professionally with passengers, clients and the office","Protect personal information and complete accurate handovers"],lessons:[{title:"Ready for duty",teaching:"Professional standards begin before the engine starts. Arrive prepared, fit for duty and with the job details understood. Never allow timetable pressure to override a safe or lawful decision.",activity:"Sort a pre-duty checklist into essential checks and items that can wait."},{title:"Communication and conduct",teaching:"Use calm, factual language. Report delays and changes promptly when safe. Do not argue, speculate or promise something outside your authority.",activity:"Choose the best response to a passenger who is unhappy about a delay."},{title:"Privacy and handover",teaching:"Passenger details, lists, photographs and travel arrangements must only be shared for an authorised purpose. Handover unresolved matters clearly.",activity:"Spot the personal information accidentally exposed in a sample handover."}],scenario:{prompt:"A passenger demands an unsafe shortcut because the coach is late. What is the professional response?",choices:["Take it to avoid a complaint","Stay calm, explain you will use a suitable safe route and update the office","Argue that the delay is not your fault","Ignore the passenger"],best:1,feedback:"Professional service never means compromising safety. Explain calmly and communicate the operational issue."},resources:[{label:"DVSA guidance for PCV drivers",url:"https://www.gov.uk/government/publications/guidance-for-vocational-drivers/guidance-for-drivers-passenger-carrying-vehicles-pcvs",kind:"guidance"}]},
{id:"vehicle-safety",title:"Vehicle Safety and Physical Walkaround Checks",category:"Vehicle and road safety",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual refresher, practical frequency set by management",summary:"Teach drivers to physically inspect the coach, recognise safety-critical defects and understand the 29-point PSV check.",outcomes:["Carry out a systematic physical inspection","Recognise defects involving tyres, wheels, brakes, visibility, doors and exits","Keep an unsafe vehicle out of service and report defects"],lessons:[{title:"Why the check matters",teaching:"The driver is responsible for ensuring the vehicle is safe before use. A digital checklist records the check, it does not replace looking, touching where appropriate, listening and assessing the vehicle.",activity:"Explore a labelled coach diagram and identify the inspection zones."},{title:"The 29-point PSV check",teaching:"Work methodically around the cab, passenger saloon and exterior. Include mirrors, glass, warning lamps, steering, brakes, doors, accessibility equipment, seats, exits, fire extinguisher, first aid kit, tyres, lights, leaks and vehicle-specific systems.",activity:"Tap each inspection zone on an interactive coach illustration."},{title:"Defect decisions",teaching:"Assess what you find, record accurate details and report through the company process. A dangerous defect must be rectified before the vehicle continues.",activity:"Classify sample findings as safe to use, report and seek instruction, or do not use."}],scenario:{prompt:"You find a damaged tyre with exposed cords during the walkaround. What should you do?",choices:["Record it and drive carefully","Do not use the vehicle, report it and obtain engineering clearance","Ask another driver if it looks acceptable","Ignore it if the pressure is correct"],best:1,feedback:"A dangerous tyre defect means the vehicle must not be used until the issue is properly resolved."},resources:[{label:"Official DVSA PSV walkaround video",url:"https://www.youtube.com/watch?v=cQ367EkH_2c",kind:"video"},{label:"DVSA PSV walkaround guidance",url:"https://www.gov.uk/guidance/carry-out-psv-daily-walkaround-checks",kind:"guidance"},{label:"DVSA 29-point PSV checklist",url:"https://assets.publishing.service.gov.uk/media/657c7c9a1c0c2a000d18ce77/public-service-vehicle-walkaround-check.pdf",kind:"guidance"}]},
{id:"freeway-defects",title:"Freeway and Defect Reporting",category:"Vehicle and road safety",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review and following reporting failures",summary:"Swans-specific learning on using Freeway as the walkaround and defect-reporting app, escalating critical warnings and following engineering instructions.",outcomes:["Use Freeway accurately after physically inspecting the vehicle","Understand critical defect and not-roadworthy warnings","Escalate defects to the office and Peter in Engineering, and wait for formal clearance"],lessons:[{title:"Freeway records the check",teaching:"Freeway is the walkaround and defect-reporting app. It is not a substitute for the physical inspection. Record what you actually checked and found.",activity:"Work through a simulated Freeway check and identify incomplete or inaccurate entries."},{title:"Critical warnings",teaching:"Never ignore, bypass or acknowledge-and-proceed after a critical defect or not-roadworthy warning. Keep the vehicle out of service, notify the office and contact Peter in Engineering.",activity:"Choose the correct action for a series of Freeway warning screens."},{title:"Clearance and audit trail",teaching:"Only use the vehicle again after Engineering has assessed the defect and formal clearance has been given. Ensure the record accurately reflects the report and instructions.",activity:"Rebuild the timeline of a defect report from discovery to clearance."}],scenario:{prompt:"Freeway displays a critical defect warning before departure. What happens next?",choices:["Acknowledge it and take passengers","Keep the vehicle out of service, notify the office and contact Peter in Engineering","Clear the warning and check it later","Ask another driver to sign it off"],best:1,feedback:"A critical warning must not be bypassed. Engineering must assess and formally clear the vehicle before use."},resources:[{label:"DVSA walkaround and defect reporting guidance",url:"https://www.gov.uk/guidance/carry-out-psv-daily-walkaround-checks",kind:"guidance"}]},
{id:"drivers-hours",title:"Drivers' Hours and Tachograph",category:"Legal and compliance",level:"Core",duration:"85–90 min",refreshMonths:12,refreshNote:"Suggested annual refresher, verify against current rule changes",summary:"Understand which drivers' hours regime applies, driving limits, breaks, daily and weekly rest, tachograph use and records.",outcomes:["Identify the applicable EU or domestic rules for a duty","Record activities and manual entries accurately","Plan breaks and rest without relying on assumptions"],lessons:[{title:"Which rules apply?",teaching:"Different passenger operations can fall under different rules and exemptions. Identify the operation, vehicle, journey and applicable regime before applying limits. Do not mix EU and domestic rules.",activity:"Use a decision tree to identify the rule set for example duties."},{title:"Breaks, driving and rest",teaching:"Understand the limits and required breaks and rest periods for the applicable regime. A timetable or passenger request cannot override legal requirements.",activity:"Build a compliant duty from a timeline and find the break point."},{title:"Tachograph operation",teaching:"Use the driver card correctly, select the correct activity, make required manual entries and report card or equipment problems. Never falsify or manipulate records.",activity:"Interpret sample tachograph activity and correct missing periods."}],scenario:{prompt:"Your journey is delayed and continuing would put your required break at risk. What should you do?",choices:["Continue and make the break up later","Contact the office early and take the required break safely","Record other work as rest","Ask a passenger to confirm the delay"],best:1,feedback:"Plan ahead, communicate early and take the break required by the rule set that applies."},resources:[{label:"DVSA drivers' hours for passenger vehicles",url:"https://www.gov.uk/guidance/drivers-hours-passenger-vehicles",kind:"guidance"},{label:"PCV driver guidance",url:"https://www.gov.uk/government/publications/guidance-for-vocational-drivers/guidance-for-drivers-passenger-carrying-vehicles-pcvs",kind:"guidance"}]},
{id:"wtd",title:"Working Time Directive for Mobile Workers",category:"Legal and compliance",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review",summary:"Distinguish working time from driving time, understand breaks, availability, records and fatigue responsibilities.",outcomes:["Recognise periods that count as working time","Understand the applicable break and working-time requirements","Record activity accurately and raise scheduling concerns"],lessons:[{title:"Working time or availability?",teaching:"Driving, loading, passenger assistance, checks and other duties may count as working time. Periods of availability and breaks have specific definitions. Record the activity that actually occurred.",activity:"Classify realistic coach duty activities."},{title:"Breaks and limits",teaching:"Understand the working-time rules that apply to the operation and how they interact with drivers' hours. A compliant driving schedule does not automatically mean working-time compliance.",activity:"Review a sample split duty and identify whether the gap qualifies."},{title:"Records and fatigue",teaching:"Keep accurate records, report errors and raise concerns where a planned duty risks breaching limits or leaving you unfit to drive.",activity:"Inspect a weekly record and flag inconsistencies."}],scenario:{prompt:"A schedule includes a long gap between duties, but the gap is only 2 hours. Can it automatically be treated as a split duty under the company rule described in this training?",choices:["Yes, any gap qualifies","No, the company split-duty rule requires a gap greater than 3 hours","Only if the driver leaves the depot","Yes, if the driver has a meal"],best:1,feedback:"For Swans scheduling, split duty is only used where the gap is greater than 3 hours. Always apply the relevant legal and company rules."},resources:[{label:"DVSA drivers' hours guidance",url:"https://www.gov.uk/guidance/drivers-hours-passenger-vehicles",kind:"guidance"},{label:"Working time for mobile workers",url:"https://www.gov.uk/government/publications/working-time-regulations-guidance-for-mobile-workers",kind:"guidance"}]},
{id:"customer-service",title:"Customer Service and Passenger Experience",category:"Passenger experience",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review and after relevant complaints",summary:"Deliver a welcoming, reliable and helpful passenger experience while keeping safety, dignity and professional boundaries central.",outcomes:["Create a positive first impression and communicate clearly","Handle complaints, delays and difficult interactions professionally","Take ownership of passenger concerns and escalate appropriately"],lessons:[{title:"First impressions and service basics",teaching:"Passengers judge the service through punctuality, presentation, cleanliness, driving smoothness, courtesy and the way information is shared. Be welcoming without making promises you cannot keep.",activity:"Compare two passenger welcome interactions and identify the behaviours that build confidence."},{title:"Complaints and service recovery",teaching:"Listen without interrupting, acknowledge the concern, establish the facts, explain what you can do and refer matters you cannot resolve. Never argue while responsible for a moving vehicle.",activity:"Practise a complaint conversation using branching response choices."},{title:"Delays, comfort and ownership",teaching:"Keep passengers informed about delays when safe, manage reasonable comfort requests and report vehicle or service issues. Customer care does not mean unsafe driving or unauthorised route changes.",activity:"Prioritise a set of passenger requests during a delayed journey."}],scenario:{prompt:"A passenger is angry because the coach is delayed and demands that you drive faster. What is the best response?",choices:["Promise to make up the time by speeding","Acknowledge the frustration, explain you will drive safely and update the office","Tell them it is not your problem","Stop in an unsafe place to discuss it"],best:1,feedback:"Good service combines empathy and clear communication with safe, lawful driving."},resources:[{label:"PCV driver guidance",url:"https://www.gov.uk/government/publications/guidance-for-vocational-drivers/guidance-for-drivers-passenger-carrying-vehicles-pcvs",kind:"guidance"},{label:"Skills England bus and coach driver occupational standard",url:"https://occupational-maps.skillsengland.education.gov.uk/maps/occupation/OCC0338A",kind:"guidance"}]},
{id:"safeguarding",title:"Passenger Care and Safeguarding",category:"Passenger experience",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review, follow company safeguarding policy",summary:"Recognise safeguarding concerns, maintain appropriate boundaries and respond to disclosures or immediate welfare risks.",outcomes:["Recognise signs that a passenger may be at risk","Respond calmly to a disclosure without investigating","Report concerns promptly through the correct safeguarding route"],lessons:[{title:"Duty of care and boundaries",teaching:"Treat passengers fairly and respectfully. Maintain professional boundaries, follow passenger release arrangements and never make assumptions about who is authorised to collect a child.",activity:"Identify boundary breaches in short passenger interaction examples."},{title:"Recognising a concern",teaching:"A concern may arise from something seen, heard or disclosed. Do not promise secrecy, lead the person or investigate. Listen, reassure and record their words accurately.",activity:"Choose what to say when a young passenger shares a worry."},{title:"Reporting and immediate safety",teaching:"Follow the company's safeguarding process and escalate promptly to the designated contact. If someone is in immediate danger, seek emergency assistance.",activity:"Put the response and reporting steps in the correct order."}],scenario:{prompt:"A young passenger tells you something that suggests they may be unsafe at home. What should you do?",choices:["Promise not to tell anyone","Ask detailed leading questions to establish proof","Listen, reassure them, avoid promising secrecy and report promptly through safeguarding procedures","Discuss it with other passengers"],best:2,feedback:"Listen and report. Do not investigate or promise confidentiality."},resources:[{label:"Keeping children safe in education",url:"https://www.gov.uk/government/publications/keeping-children-safe-in-education--2",kind:"guidance"},{label:"PCV driver guidance",url:"https://www.gov.uk/government/publications/guidance-for-vocational-drivers/guidance-for-drivers-passenger-carrying-vehicles-pcvs",kind:"guidance"}]},
{id:"accessibility",title:"Accessibility and Disability Awareness",category:"Passenger experience",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review, equipment sign-off separately",summary:"Support disabled passengers and people with additional needs respectfully, safely and without assumptions.",outcomes:["Communicate directly and respectfully with passengers","Use accessibility equipment only when trained and authorised","Protect dignity, independence and safe boarding"],lessons:[{title:"Respectful assistance",teaching:"Ask the passenger what assistance they need rather than assuming. Speak to the passenger, not only to a companion. Respect personal space, mobility aids and individual choices.",activity:"Match passenger requests with respectful responses."},{title:"Ramps, lifts and mobility equipment",teaching:"Follow the vehicle and equipment instructions and company procedures. Do not operate unfamiliar equipment without training. Check the area, secure the equipment and passenger as instructed.",activity:"Explore an interactive sequence for safe equipment preparation."},{title:"Boarding and journey support",teaching:"Allow sufficient time, keep access routes clear and confirm the passenger is safely positioned before moving. Never rush someone because of timetable pressure.",activity:"Spot hazards in a simulated boarding scene."}],scenario:{prompt:"A passenger asks for help with a wheelchair lift, but you have not been trained on that model. What should you do?",choices:["Try it and learn as you go","Ask the passenger to operate it","Pause, explain and obtain help from someone trained and authorised","Cancel the passenger's journey"],best:2,feedback:"Never improvise with accessibility equipment. Get trained assistance and follow the correct procedure."},resources:[{label:"Buses and coaches, features and help for disabled people",url:"https://www.gov.uk/government/publications/buses-and-coaches-features-and-help-for-disabled-people/buses-and-coaches-features-and-help-for-disabled-people",kind:"guidance"},{label:"DfT REAL disability equality training resources",url:"https://www.drivingforbetterbusiness.com/dvsa/taxi/",kind:"interactive"}]},
{id:"defensive-driving",title:"Defensive Driving and Hazard Perception",category:"Driving skills",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review and targeted after incidents",summary:"Develop anticipation, space management, speed choice and protection of passengers and vulnerable road users.",outcomes:["Identify developing hazards early","Maintain safe separation and appropriate speed","Adapt driving to weather, traffic, road layout and passenger comfort"],lessons:[{title:"Anticipation and observation",teaching:"Scan well ahead, check mirrors regularly and identify clues that a hazard may develop. Look for vulnerable road users, junctions, parked vehicles and changing traffic conditions.",activity:"Pause a series of road scenes and select developing hazards."},{title:"Space and speed",teaching:"Choose a speed that allows time and space to respond. Increase separation in poor conditions and avoid harsh acceleration, braking and steering that can affect passengers.",activity:"Adjust following distance and speed in a changing-weather simulator."},{title:"Vulnerable road users",teaching:"Give cyclists, pedestrians, motorcyclists and other vulnerable road users room. Check blind spots before moving and never assume another road user has seen the coach.",activity:"Identify blind spots and safe observation points around a coach."}],scenario:{prompt:"Traffic ahead suddenly slows on a wet motorway. What is the safest response?",choices:["Brake sharply at the last moment","Ease off early, increase the gap and brake progressively as needed","Move lanes without checking mirrors","Accelerate to get past the queue"],best:1,feedback:"Early anticipation, space and progressive control reduce risk to passengers and other road users."},resources:[{label:"National standard for driving buses and coaches",url:"https://assets.publishing.service.gov.uk/media/5a756befed915d6faf2b2dbc/national-standard-for-driving-buses-and-coaches.pdf",kind:"guidance"},{label:"Highway Code",url:"https://www.gov.uk/guidance/the-highway-code",kind:"guidance"}]},
{id:"reversing",title:"Reversing and Manoeuvring",category:"Driving skills",level:"Specialist",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review, practical observation required",summary:"Reduce low-speed collisions through preparation, observation, controlled manoeuvres and effective banksman communication.",outcomes:["Assess the manoeuvre area before moving","Use a trained banksman where required and agree signals","Stop immediately if the banksman is lost from view or the manoeuvre becomes unsafe"],lessons:[{title:"Prepare before reversing",teaching:"Avoid reversing where possible. Get out and look, assess overhead and ground hazards, pedestrians, fixed objects and available space. Do not rely solely on cameras.",activity:"Mark hazards on a depot reversing plan."},{title:"Banksman communication",teaching:"Agree the method and signals before starting. Move slowly and stop if instructions are unclear or the banksman is no longer visible. Never continue blind.",activity:"Match banksman signals to the correct driver response."},{title:"Tight spaces and recovery",teaching:"Use a controlled manoeuvre, make repeated observations and stop if the situation changes. Reposition rather than forcing a tight turn.",activity:"Choose a safe manoeuvre plan for a constrained depot bay."}],scenario:{prompt:"You are reversing with a banksman and lose sight of them in the mirror. What do you do?",choices:["Continue slowly","Stop immediately and do not move until communication is re-established","Use the camera and continue","Sound the horn and keep moving"],best:1,feedback:"If sight of the banksman is lost, stop immediately. Do not move again until it is safe and communication is clear."},resources:[{label:"HSE workplace transport safety",url:"https://www.hse.gov.uk/workplacetransport/",kind:"guidance"},{label:"National standard for driving buses and coaches",url:"https://assets.publishing.service.gov.uk/media/5a756befed915d6faf2b2dbc/national-standard-for-driving-buses-and-coaches.pdf",kind:"guidance"}]},
{id:"route-planning",title:"Route Planning, Low Bridges and Journey Risk",category:"Driving skills",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review",summary:"Plan coach-suitable routes, check dimensions and restrictions, anticipate disruption and avoid over-reliance on satnav.",outcomes:["Confirm vehicle dimensions and restrictions","Identify low bridges, weight limits, narrow roads and access constraints","Reassess the route when conditions or instructions change"],lessons:[{title:"Plan for the vehicle",teaching:"A route suitable for a car may not be suitable for a coach. Check height, width, weight, turning space, access restrictions, stops and destination arrangements.",activity:"Compare two routes and identify coach-specific risks."},{title:"Bridge and access risk",teaching:"Know the vehicle's actual height and use reliable restriction information. Never guess clearance or follow satnav blindly. If uncertain, stop in a safe place and seek verified advice.",activity:"Read restriction signs and select a safe route."},{title:"Dynamic journey planning",teaching:"Roadworks, weather, congestion and closures can change the risk. Reassess and communicate with the office rather than making an unsafe last-minute decision.",activity:"Re-plan a journey after a bridge closure and traffic diversion."}],scenario:{prompt:"Your satnav directs you towards a low bridge but you cannot verify the clearance for your coach. What should you do?",choices:["Follow the satnav slowly","Proceed if other vehicles are using it","Do not enter, stop safely and verify a suitable route","Drive down the centre of the road"],best:2,feedback:"Never guess bridge clearance. Verify the route and use a suitable alternative."},resources:[{label:"National standard for driving buses and coaches",url:"https://assets.publishing.service.gov.uk/media/5a756befed915d6faf2b2dbc/national-standard-for-driving-buses-and-coaches.pdf",kind:"guidance"},{label:"Highway Code",url:"https://www.gov.uk/guidance/the-highway-code",kind:"guidance"}]},
{id:"emergencies",title:"Emergency Procedures, Breakdowns and Collisions",category:"Emergency response",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review and after relevant incidents",summary:"Protect life, assess the scene, communicate clearly and follow company and emergency service instructions.",outcomes:["Make the scene as safe as possible","Call emergency services when required and give clear information","Protect passengers and record accurate incident details"],lessons:[{title:"First actions and scene safety",teaching:"Stop safely, assess immediate danger, protect yourself and passengers and call emergency services where needed. Do not put yourself at risk to retrieve property or investigate damage.",activity:"Order the first actions after a collision."},{title:"Breakdown management",teaching:"Follow the company breakdown process, choose a safe stopping place, make the vehicle visible and keep passengers informed. Do not attempt repairs beyond your competence.",activity:"Select safe actions for a motorway breakdown."},{title:"Information and reporting",teaching:"Provide accurate location, vehicle, passenger and incident details. Record what happened factually and preserve relevant evidence in line with company procedure.",activity:"Complete a sample incident information report."}],scenario:{prompt:"Your coach breaks down on a motorway hard shoulder with passengers aboard. What is the priority?",choices:["Ask passengers to stand beside the coach","Follow the emergency procedure, assess the safest passenger arrangements and contact the appropriate services and control","Attempt a roadside repair immediately","Leave passengers and walk to the next junction"],best:1,feedback:"Passenger and personal safety come first. Follow the specific motorway breakdown procedure and instructions."},resources:[{label:"National standard for driving buses and coaches",url:"https://assets.publishing.service.gov.uk/media/5a756befed915d6faf2b2dbc/national-standard-for-driving-buses-and-coaches.pdf",kind:"guidance"},{label:"HSE workplace transport safety",url:"https://www.hse.gov.uk/workplacetransport/",kind:"guidance"}]},
{id:"fire-evacuation",title:"Fire Safety and Passenger Evacuation",category:"Emergency response",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review, practical familiarisation required",summary:"Recognise fire indicators, stop safely, raise the alarm, evacuate when necessary and account for passenger welfare.",outcomes:["Recognise when a fire or smoke event requires stopping and evacuation","Use safe evacuation routes and keep passengers away from danger","Understand extinguisher limitations and never expose yourself to unnecessary risk"],lessons:[{title:"Recognise and respond",teaching:"Smoke, burning smells, warning indicators or visible flames require prompt assessment. Stop in a safe place, raise the alarm and follow company procedures.",activity:"Identify warning signs in a coach cab scenario."},{title:"Evacuation decisions",teaching:"Choose the safest exit and assembly location based on traffic, fire, smoke and other hazards. Give clear instructions and prevent passengers returning to the vehicle.",activity:"Select an evacuation route from a coach scene."},{title:"Equipment and personal safety",teaching:"Know where safety equipment is and its limitations. Only tackle a small fire if trained, safe to do so and with a clear escape route. Do not open an engine housing wide to fight an engine fire.",activity:"Match equipment to its purpose and identify unsafe actions."}],scenario:{prompt:"You see smoke coming from the engine area. What is the safest response?",choices:["Open the engine cover fully and investigate","Stop safely, raise the alarm, move passengers to a safe place and follow emergency procedures","Continue to the depot","Ask passengers to check the engine"],best:1,feedback:"Protect life first. Avoid opening an engine housing wide because this can feed a fire."},resources:[{label:"National standard for driving buses and coaches",url:"https://assets.publishing.service.gov.uk/media/5a756befed915d6faf2b2dbc/national-standard-for-driving-buses-and-coaches.pdf",kind:"guidance"},{label:"HSE fire safety",url:"https://www.hse.gov.uk/fireandexplosion/",kind:"guidance"}]},
{id:"school-transport",title:"School Transport and Young Passenger Safety",category:"Passenger experience",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review and school contract briefing",summary:"Manage safe boarding, passenger behaviour, safeguarding boundaries, authorised release arrangements and communication with schools.",outcomes:["Apply the correct boarding and passenger release arrangements","Maintain professional boundaries and safeguarding awareness","Respond consistently to behaviour or welfare concerns"],lessons:[{title:"Before the school journey",teaching:"Understand the route, collection points, passenger list, contract instructions and any individual requirements. Keep passenger information secure.",activity:"Check a sample school route pack for missing information."},{title:"Boarding and behaviour",teaching:"Manage boarding calmly, confirm passengers are safely seated and follow seatbelt requirements. Address behaviour without confrontation or distraction from driving.",activity:"Choose proportionate responses to common school passenger situations."},{title:"Passenger release and safeguarding",teaching:"Follow the agreed release procedure. Never release a child to an unauthorised adult or change arrangements based on pressure. Escalate uncertainty to the office.",activity:"Work through a branching passenger collection scenario."}],scenario:{prompt:"An adult you do not recognise asks you to release a child to them, saying the parent is running late. What should you do?",choices:["Release the child because the adult knows their name","Follow the authorised release process and contact the office if uncertain","Ask another child if they know the adult","Let the adult take the child if they show a phone message"],best:1,feedback:"Follow the documented release arrangements. If there is any uncertainty, keep the child safe and contact the office."},resources:[{label:"Keeping children safe in education",url:"https://www.gov.uk/government/publications/keeping-children-safe-in-education--2",kind:"guidance"},{label:"PCV driver guidance",url:"https://www.gov.uk/government/publications/guidance-for-vocational-drivers/guidance-for-drivers-passenger-carrying-vehicles-pcvs",kind:"guidance"}]},
{id:"accident-reporting",title:"Accident and Incident Reporting",category:"Safety and reporting",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Suggested annual review and after reportable incidents",summary:"Understand immediate notifications, factual evidence, passenger information, defect links and timely incident reporting.",outcomes:["Make the scene safe and notify the right people promptly","Record accurate facts without speculation or blame","Preserve evidence and cooperate with the company's investigation"],lessons:[{title:"Immediate response",teaching:"Prioritise safety and emergency assistance. Notify the office as soon as it is safe and follow instructions. Do not admit liability or speculate about cause.",activity:"Build the correct first-hour incident response timeline."},{title:"Evidence and factual reporting",teaching:"Record date, time, location, vehicle, people involved, witnesses, damage and events. Separate what you saw from what someone told you. Preserve relevant photographs and records through approved channels.",activity:"Review a sample report and identify opinion, missing facts and contradictions."},{title:"Follow-up and learning",teaching:"Cooperate with interviews and requests for information. Report defects or near misses and understand that incident reviews aim to establish facts and prevent recurrence.",activity:"Link incident findings to a suitable learning or remedial action."}],scenario:{prompt:"After a minor collision, a passenger asks you to tell them who was at fault. What should you do?",choices:["Give your personal opinion","Argue with the other driver","Ensure safety, exchange/report required details and provide factual information through the proper process","Post photographs online"],best:2,feedback:"Stay factual, follow legal and company reporting requirements and do not speculate about liability."},resources:[{label:"National standard for driving buses and coaches",url:"https://assets.publishing.service.gov.uk/media/5a756befed915d6faf2b2dbc/national-standard-for-driving-buses-and-coaches.pdf",kind:"guidance"},{label:"DVSA PCV driver guidance",url:"https://www.gov.uk/government/publications/guidance-for-vocational-drivers/guidance-for-drivers-passenger-carrying-vehicles-pcvs",kind:"guidance"}]},
{id:"cpc-development",title:"Professional Development and CPC Support",category:"Development",level:"Core",duration:"15–20 min",refreshMonths:12,refreshNote:"Annual learning plan review, CPC deadlines tracked separately",summary:"Help drivers understand their development record, annual learning expectations, CPC planning and how to access support.",outcomes:["Understand the purpose of periodic Driver CPC training","Plan modules against the applicable qualification deadline","Review training gaps and discuss development needs"],lessons:[{title:"Your development record",teaching:"The academy records internal learning, assessment outcomes and practical sign-offs. These records do not automatically prove that a Driver CPC course is approved or that periodic training hours have been uploaded.",activity:"Explore a sample training passport and identify missing evidence."},{title:"Planning CPC learning",teaching:"Check the driver's actual Driver CPC status, deadline and approved training records. Build a plan that spreads learning sensibly and avoids leaving required hours until the last minute.",activity:"Create a two-year learning plan from a sample CPC record."},{title:"Reflect and improve",teaching:"Use feedback, incidents, assessments and personal goals to identify useful learning. Discuss support with a manager rather than treating training as a punishment.",activity:"Choose development actions from a sample driver review."}],scenario:{prompt:"A driver completes an internal academy module. Can it automatically be counted as an approved Driver CPC periodic training hour?",choices:["Yes, every online module counts","Only if it has the required approval and is delivered and recorded under the applicable Driver CPC arrangements","Yes, if the quiz score is 100%","Only if the driver downloads a certificate"],best:1,feedback:"Internal academy completion and approved Driver CPC hours are separate records. Never represent an internal course as CPC-accredited unless it is properly approved."},resources:[{label:"Driver CPC training requirements",url:"https://www.gov.uk/driver-cpc-training",kind:"guidance"},{label:"DVSA guidance for vocational drivers",url:"https://www.gov.uk/government/publications/guidance-for-vocational-drivers/guidance-for-drivers-passenger-carrying-vehicles-pcvs",kind:"guidance"}]},
{id:"practical-assessments",title:"Practical Competence Assessments",category:"Practical sign-off",level:"Practical",duration:"Assessor-led practical session",refreshMonths:null,refreshNote:"Set per skill, vehicle type and company assessment policy",summary:"Assessor-led verification of skills that cannot be signed off by an online quiz.",outcomes:["Demonstrate a physical walkaround and defect report","Demonstrate safe use of relevant accessibility equipment","Demonstrate reversing, manoeuvring and emergency actions where required"],lessons:[{title:"Assessment preparation",teaching:"The assessor confirms the skill, vehicle or equipment, assessment criteria and safe conditions. The driver must explain and demonstrate the task, not simply confirm they have read about it.",activity:"Review the assessment checklist and evidence requirements."},{title:"Observed demonstration",teaching:"The assessor records observed actions, any prompts, deficiencies and whether the standard was met. Unsafe actions require the assessment to stop.",activity:"Use an observation checklist with clear pass, further practice and not yet competent outcomes."},{title:"Feedback and reassessment",teaching:"Give specific feedback and agree further practice where needed. Record the assessor, date, vehicle/equipment and next review date.",activity:"Turn assessment observations into an individual development plan."}],scenario:{prompt:"A driver passes the online accessibility lesson but has not demonstrated the lift on the vehicle. What is their status?",choices:["Fully competent on the lift","Practical sign-off remains outstanding","The online quiz replaces the practical demonstration","No further assessment is ever needed"],best:1,feedback:"Online knowledge and practical competence are separate. Record the practical sign-off only after observed assessment."},resources:[{label:"Skills England bus and coach driver occupational standard",url:"https://occupational-maps.skillsengland.education.gov.uk/maps/occupation/OCC0338A",kind:"guidance"}]},
{id:"remedial-learning",title:"Targeted and Remedial Driver Learning",category:"Development",level:"Specialist",duration:"Assigned to need",refreshMonths:null,refreshNote:"Set by manager after review of incident, complaint or assessment",summary:"Allocate focused learning after an incident, infringement, complaint, near miss or observed skills gap.",outcomes:["Understand the reason for targeted learning","Complete the relevant refresher and scenario practice","Agree evidence of improvement and any follow-up observation"],lessons:[{title:"Learning from an event",teaching:"A remedial assignment should be relevant, proportionate and based on established facts. Explain the learning objective and expected improvement to the driver.",activity:"Match common events to relevant training topics."},{title:"Focused refresher",teaching:"Complete the assigned learning and apply it to realistic situations. A quiz result alone may not demonstrate changed behaviour where practical observation is needed.",activity:"Complete a targeted scenario based on the assigned risk."},{title:"Review and follow-up",teaching:"The manager records completion, feedback and any required observation or follow-up. Keep training records factual and distinguish training from disciplinary outcomes.",activity:"Choose evidence that would demonstrate improvement."}],scenario:{prompt:"A mirror strike occurs during a reversing manoeuvre. Which learning response is most relevant?",choices:["Assign unrelated tachograph training","Consider reversing and manoeuvring refresher, followed by practical observation if appropriate","Automatically mark the driver incompetent","Delete the incident once training is assigned"],best:1,feedback:"Target the learning to the risk and verify improvement with an appropriate method."},resources:[{label:"HSE workplace transport safety",url:"https://www.hse.gov.uk/workplacetransport/",kind:"guidance"}]}
];
