export type AcademyKnowledgeCheck={question:string;options:string[];best:number;feedback:string};
export const academyKnowledgeChecks:Record<string,AcademyKnowledgeCheck>={
"professional-standards":{question:"A passenger asks you for another passenger's contact details. What should you do?",options:["Share them if the passenger seems genuine","Politely refuse and explain that personal details cannot be shared","Show them the booking list","Ask another passenger"],best:1,feedback:"Protect personal information. Only share it through an authorised process."},
"vehicle-safety":{question:"Which statement best describes a proper walkaround?",options:["Complete the app without leaving the cab","Physically inspect the vehicle systematically and record what you actually find","Only check items that failed yesterday","Ask another driver if the vehicle is safe"],best:1,feedback:"The app supports the check, it never replaces the physical inspection."},
"freeway-defects":{question:"Freeway shows a critical not-roadworthy warning. What is the correct status?",options:["Available if the driver accepts the warning","Out of service until Engineering assesses and formally clears it","Available for an empty repositioning journey","Available if the office is busy"],best:1,feedback:"Do not bypass a critical warning. Keep the vehicle out of service and escalate."},
"drivers-hours":{question:"What should you establish before calculating a driving limit?",options:["Which drivers' hours regime applies to that operation","How many passengers are booked","Whether the journey is profitable","The route's fuel cost"],best:0,feedback:"Identify the applicable regime first. Different rules and exemptions must not be mixed."},
"wtd":{question:"Does a compliant driving schedule automatically prove working-time compliance?",options:["Yes, they are identical","No, working time has separate definitions and requirements","Only on school work","Only if the driver takes a meal"],best:1,feedback:"Driving time and working time are different compliance measures."},
"customer-service":{question:"A passenger makes a reasonable complaint while you are driving. What comes first?",options:["Turn around and debate it","Stay focused on driving, then respond or arrange follow-up when safe","Ignore all complaints","Promise compensation"],best:1,feedback:"Never allow a complaint to distract from safe control of the coach."},
"safeguarding":{question:"A young passenger makes a concerning disclosure. Which response is appropriate?",options:["Promise complete secrecy","Ask leading questions until you are certain","Listen, reassure, avoid investigating and report promptly","Discuss it with other passengers"],best:2,feedback:"Listen and report through safeguarding procedures. Do not investigate."},
"accessibility":{question:"What should you do before assisting with unfamiliar mobility equipment?",options:["Experiment with the controls","Ask the passenger to show you while it is moving","Pause and obtain help from someone trained and authorised","Skip the equipment checks"],best:2,feedback:"Only operate equipment you are trained and authorised to use."},
"defensive-driving":{question:"What is the main benefit of scanning well ahead?",options:["It lets you drive closer to the vehicle ahead","It gives more time to recognise and respond to developing hazards","It removes the need for mirror checks","It means speed limits do not matter"],best:1,feedback:"Early observation gives time and space to respond smoothly."},
"reversing":{question:"When should a reversing manoeuvre stop?",options:["Only when the horn sounds","If the banksman is lost from view or communication becomes unclear","Only if a passenger complains","When the driver reaches the bay"],best:1,feedback:"Stop immediately if you lose sight of the banksman. Re-establish safe communication."},
"route-planning":{question:"A route is recommended by satnav but coach clearance is uncertain. What is correct?",options:["Follow it slowly","Use it if cars are passing","Stop safely and verify a suitable coach route before proceeding","Ask a passenger to watch the roof"],best:2,feedback:"Satnav is not a substitute for checking vehicle restrictions and route suitability."},
"emergencies":{question:"At an incident, what takes priority?",options:["Protecting the vehicle","Getting the job finished","Personal and passenger safety, then emergency assistance and reporting","Taking photographs first"],best:2,feedback:"Protect life first. Evidence and administration follow when safe."},
"fire-evacuation":{question:"When is it appropriate to use a fire extinguisher?",options:["Whenever smoke is seen, regardless of risk","Only if trained, the fire is small, it is safe and there is a clear escape route","Instead of evacuating passengers","After opening the engine housing fully"],best:1,feedback:"Never put yourself or passengers at unnecessary risk. Evacuate and call for help."},
"school-transport":{question:"An adult requests a change to a child's agreed release arrangement. What should you do?",options:["Agree if they sound confident","Follow the authorised process and contact the office if uncertain","Ask the child to decide","Release the child if the adult knows their name"],best:1,feedback:"Never change passenger release arrangements without proper authorisation."},
"accident-reporting":{question:"How should an incident report describe what happened?",options:["Include assumptions about who was to blame","Record factual observations and distinguish them from what others said","Leave out details that may be inconvenient","Use social media posts as the official report"],best:1,feedback:"Accurate, objective records support fair investigation and learning."},
"cpc-development":{question:"Can an internal academy module automatically count as approved Driver CPC periodic training?",options:["Yes, if the quiz is passed","No, it must meet the applicable approval and recording requirements","Yes, if a certificate is downloaded","Only if it lasts 30 minutes"],best:1,feedback:"Internal learning records and approved Driver CPC hours must be kept distinct."},
"practical-assessments":{question:"A driver completes the online course but has not demonstrated the practical skill. What is the result?",options:["Competent","Practical sign-off remains outstanding","The online quiz replaces the assessment","No record is needed"],best:1,feedback:"Knowledge completion and observed practical competence are separate."},
"remedial-learning":{question:"What makes a remedial assignment effective?",options:["Assign any available course","Match learning to the identified risk and verify improvement appropriately","Use it automatically as a disciplinary penalty","Close the incident without follow-up"],best:1,feedback:"Training should be relevant, proportionate and linked to a clear learning objective."}
};
